mapper.select:
SELECT COUNT(*) FROM schedule_shifts s
WHERE s.company_id = #{companyId}
  AND s.shift_date >= #{today}
  AND s.status NOT IN ('CANCELLED', 'CHECKED_OUT', 'COMPLETED')

SELECT COUNT(*) FROM attendance_records a
WHERE a.company_id = #{companyId}
  AND (a.status IS NOT NULL AND a.status != 'NORMAL' OR a.check_in_time IS NULL OR a.check_out_time IS NULL)
